// R3: mark draft sent + record how many messages went out.
// Phase C (Redis-migration): status is persisted to Redis by 'Sync
// Sent To Redis'; here we just compute the count from the Redis draft
// (Parse Callback). staticData write removed.
const pc = $('Parse Callback').item.json;
const draftId = pc.draft_id;
const d = pc.draft || {};
const cnt = Array.isArray(d.messages) ? d.messages.length : 1;
return { json: { ok: true, status: 'sent', draft_id: draftId, messages_sent_count: cnt } };

