// FR-2: parse the lead opener draft from Claude
const response = $input.item.json;
const bp = $('Build Lead Prompt').item.json;
let raw = '';
try { raw = response.content[0].text; } catch (e) {
  return { json: {
    messages: ['(empty Claude response - check API node)'],
    notes: 'ERROR: could not extract text from Claude API response',
    parse_status: 'extract_failed',
    customer_phone: bp.leadPhone, customer_name: '', user_message: bp.leadText,
    conversation_history: '', history_count: 0, is_lead: true,
  should_send_file: !!(parsed && parsed.should_send_file === true),
  file_key: (parsed && typeof parsed.file_key === 'string')
    ? parsed.file_key.trim() : '',
  file_description: (parsed && typeof parsed.file_description === 'string')
    ? parsed.file_description.trim() : '',
  } };
}
let cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
let parsed; let status = 'ok';
try {
  parsed = JSON.parse(cleaned);
  if (!Array.isArray(parsed.messages) || !parsed.messages.length) throw new Error('messages array missing or empty');
} catch (e) {
  const _rawLooksJson = /^\s*[{\[]/.test(raw);
  parsed = _rawLooksJson
    ? { messages: ['⚠️ Draft came back malformed (invalid JSON from the model) — tap 🔄 Regen for a clean draft.'], notes_for_zayn: 'parse fail (raw JSON hidden, len ' + raw.length + '): ' + e.message }
    : { messages: [raw], notes_for_zayn: '(JSON parse failed - plain text. ' + e.message + ')' };
  status = 'fallback_plain_text';
}
const messages = parsed.messages.slice(0, 4).map(m => String(m));
return { json: {
  messages: messages,
  notes: parsed.notes_for_zayn || '(no notes)',
  parse_status: status,
  customer_phone: bp.leadPhone,
  customer_name: '',
  user_message: bp.leadText,
  conversation_history: '',
  history_count: 0,
  is_lead: true,
  should_send_file: !!(parsed && parsed.should_send_file === true),
  file_key: (parsed && typeof parsed.file_key === 'string')
    ? parsed.file_key.trim() : '',
  file_description: (parsed && typeof parsed.file_description === 'string')
    ? parsed.file_description.trim() : ''
} };

// FR-3 (BUG-1 fix): the bridge buffered this message in Redis and issued
// a token. staticData is NOT used — it cannot coordinate the concurrent
// executions that one-per-inbound-message spawns.
const wh = $('WAHA Webhook').item.json.body.payload;
const r = $('Debounce Buffer').item.json || {};
// Two-tier debounce: booking-signal messages flush fast (5s) so hot leads
// get a near-instant reply; everything else waits 15s to let the customer
// finish a multi-message thought before we draft. (date-within-24h is
// proxied by today/tonight/this evening/same day — no date parsing here.)
const text = String(wh.body || '').toLowerCase();
const BOOKING_SIGNAL = /\b(today|tonight|tonite|this evening|same.?day|right now|asap|how much|price|prices|pricing|cost|rate|rates|quote|deposit|let'?s book|book (it|now|this|the)|i'?ll take it)\b/;
const wait_seconds = BOOKING_SIGNAL.test(text) ? 10 : 60;
return { json: {
  phone: wh.from,
  token: r.token || '',
  degraded: !r.token,       // bridge/Redis error -> Flush Check fails open
  wait_seconds: wait_seconds
} };

// FR-3 (BUG-1 fix): proceed only if the bridge says this is the latest
// message for the customer. Redis-backed — see bridge /debounce.
const wh = $('WAHA Webhook').item.json.body.payload;
const bm = $('Buffer Message').item.json || {};
const r = $('Debounce Flush').item.json || {};
// Suppress this draft ONLY when buffering succeeded AND the bridge says a
// newer message superseded it. Every error path falls open (process), so
// a customer message is never silently dropped.
if (bm.degraded !== true && r.latest === false) {
  return [];
}
const combined = (r.combined && String(r.combined).trim())
  ? r.combined
  : (wh.body || '');
return [{ json: {
  phone: wh.from,
  combinedMessage: combined,
  bufferedIds: (Array.isArray(r.ids) && r.ids.length) ? r.ids : [wh.id],
  bufferedCount: r.count || 1
} }];

// FR-5: improve a draft only while it is still pending (unsent)
const sid = $('Save Telegram MsgID').item.json;
const draftId = sid.draft_id;
// BUG-3 fix: the improver now runs on autonomous drafts too — Push
// Improved Text writes the improved copy into the Redis autosend key so
// the auto-send dispatches it (was: skipped armed drafts).
// Phase A (Redis-migration): use Queue & Format's in-execution
// draft object; staticData fallback.
let d = null;
try { d = ($('Queue & Format').item.json || {}).draft || null; } catch (e) { d = null; }
// Phase C (Redis-migration): staticData fallback removed (Redis-only).
if (d && d.is_payment === true) {
  // Nomod: payment drafts carry a deterministic booking block +
  // real Nomod link appended by Build Payment Message; the
  // improver doesn't know about them and would strip them.
  return [];
}
if (!d || d.status !== 'pending') {
  return [];   // sent / skipped / awaiting_edit / gone — nothing to improve
}
return [{ json: {
  draft_id: draftId,
  telegram_message_id: sid.telegram_message_id || d.telegram_message_id,
  customer_name: d.customer_name || '',
  customer_id: d.customer_phone || '',
  incoming_message: d.customer_message || '',
  history: d.conversation_history || '',
  current_draft: (Array.isArray(d.messages) && d.messages.length) ? d.messages : (d.draft_text || '')
} }];

// Quality-score badge + SHOW-THEN-UPGRADE (operator 2026-06-01).
// Reads the /quality-check score from 'Hermes Improve' and prepends a badge to
// the ORIGINAL card. If the draft scored < 8, it silently regenerates a better
// one via /draft-gated and swaps it into the card AND Redis (so Approve sends
// the improved text). Fail-open: any error leaves the original draft + badge.
const qc = $('Hermes Improve').item.json || {};
// FAIL-CLOSED (2026-06-02): only re-open a draft we can CONFIRM is still
// pending AND not being sent. Default st=null so a failed recheck bails; also
// bail on send_claimed (claim set at send-start, before status flips to 'sent')
// — closing the race where a fast send re-opened an already-sent draft.
let st = null, claimed = false;
try {
  const r = $('Recheck Draft Status').item.json || {};
  if (r.draft && r.draft.status) st = r.draft.status;
  claimed = !!r.send_claimed;
} catch (e) {}
if (st !== 'pending' || claimed) return [];
if (qc.ok !== true || typeof qc.score !== 'number') return [];

const NL = String.fromCharCode(10);
const tp = $('Queue & Format').item.json.telegram_payload;
const pending = $('Queue & Format').item.json.draft || {};
const sid = $('Save Telegram MsgID').item.json;
const bp = $('Build Prompt').item.json;

function badgeFor(s, flags, summary) {
  const reason = ((flags && flags.length) ? flags.join(', ').replace(/_/g, ' ')
                 : String(summary || '')).slice(0, 80);
  if (s >= 8) return '🟢 ' + s + '/10';
  if (s >= 5) return '🟡 ' + s + '/10' + (reason ? ' — ' + reason : '');
  return '🔴 ' + s + '/10' + (reason ? ' — ' + reason : '') + ' · tap 🔄 Regen';
}

let score = Math.max(1, Math.min(10, Math.round(qc.score)));
let cardText = (badgeFor(score, qc.flags, qc.summary) + NL + tp.text).slice(0, 4000);
let fields = {};

if (score < 8) {
  try {
    const http = this.helpers.httpRequest.bind(this.helpers);
    const bctx = (($('Fetch Behavioral Context').item.json) || {}).formatted || '';
    const g = await http({
      method: 'POST',
      url: 'http://172.18.0.1:8788/draft-gated',
      headers: { 'Content-Type': 'application/json', 'X-Bridge-Token': $env.BRIDGE_TOKEN || '' },
      body: {
        system_prompt: bp.systemPrompt,
        behavioral_context: bctx,
        conversation_history: bp.conversationHistory || '',
        user_message: bp.userMessage || '',
        customer_name: bp.customerName || '',
        customer_phone: bp.customerPhone || '',
        original_messages: (Array.isArray(pending.messages) && pending.messages.length) ? pending.messages : (pending.draft_text ? [pending.draft_text] : []),
        threshold: 8,
        max_attempts: 3
      },
      json: true,
      timeout: 150000
    });
    const newScore = (g && g.ok && typeof g.score === 'number') ? Math.max(1, Math.min(10, Math.round(g.score))) : 0;
    // 1B: compare like-for-like — the gate Anthropic-scores the ORIGINAL too
    // (g.original_score); fall back to the local-Hermes badge only if absent.
    // 4A: swap on >= (a tie regen is at least as good, and fresher).
    const baseScore = (g && typeof g.original_score === 'number') ? Math.max(1, Math.min(10, Math.round(g.original_score))) : score;
    if (g && g.ok && Array.isArray(g.messages) && g.messages.length && newScore >= baseScore) {
      const improved = g.messages.join(NL + NL);
      const orig = pending.draft_text || '';
      const fmtPrev = (ms) => ms.length === 1 ? String(ms[0]) : ms.map((m, i) => (i + 1) + '. ' + m).join(NL);
      const fmtHdr = (ms) => ms.length === 1 ? '💬 DRAFT:' : ('💬 DRAFT (' + ms.length + ' messages):');
      const nb = fmtHdr(g.messages) + NL + fmtPrev(g.messages);
      const oMsgs = Array.isArray(pending.messages) ? pending.messages.map(String) : [];
      const ob = oMsgs.length ? (fmtHdr(oMsgs) + NL + fmtPrev(oMsgs)) : '';
      let swapped;
      if (ob && tp.text.indexOf(ob) >= 0) { swapped = tp.text.split(ob).join(nb); }
      else { const dI = tp.text.indexOf('💬 DRAFT'); const nI = tp.text.indexOf(NL + NL + '📝 Notes'); swapped = (dI >= 0 && nI > dI) ? (tp.text.slice(0, dI) + nb + tp.text.slice(nI)) : (dI >= 0 ? (tp.text.slice(0, dI) + nb) : (tp.text + NL + NL + nb)); }
      cardText = (badgeFor(newScore, g.flags, g.summary) + NL + swapped).slice(0, 4000);
      fields = { draft_text: improved, original_draft_text: improved, messages: g.messages, notes: g.notes_for_zayn || pending.notes || '' };
    } else if (g && g.capped) {
      // gate exhausted max_attempts without reaching threshold
      cardText = (badgeFor(score, qc.flags, qc.summary) + ' \u00b7 auto-regen capped' + NL + tp.text).slice(0, 4000);
    }
  } catch (e) {}
}

return [{ json: {
  draft_id: sid.draft_id,
  chat_id: tp.chat_id,
  message_id: sid.telegram_message_id,
  text: cardText,
  reply_markup: tp.reply_markup,
  fields: fields
} }];

// FR-5 4.3b: assemble the /learn payload from the operator's Edit feedback
const ptr = $('Process Text Reply').item.json;
const draftId = ptr.draft_id;
// Phase A (Redis-migration): fetch the draft from Redis; staticData fallback.
const _http = this.helpers.httpRequest.bind(this.helpers);
let d = null;
try {
  const r = await _http({ method: 'POST',
    url: 'http://172.18.0.1:8788/queue',
    headers: { 'Content-Type': 'application/json',
      'X-Bridge-Token': $env.BRIDGE_TOKEN || '' },
    body: { action: 'get', draft_id: draftId }, json: true, timeout: 8000 });
  if (r && r.found && r.draft) d = r.draft;
} catch (e) { d = null; }
if (!d) d = {};   // Phase C: Redis-only (staticData fallback removed)
return [{ json: {
  feedback: ptr.feedback || '',
  draft_text: d.draft_text || '',
  customer_id: d.customer_phone || '',
  customer_name: d.customer_name || '',
  admin_chat_id: ptr.admin_chat_id || 5532831477
} }];

// FR-5 4.3b: notify the operator only when /learn actually captured a rule
const r = $input.item.json || {};
const adminChatId = $('Prep Learn').item.json.admin_chat_id || 5532831477;
if (!r.ok || !r.captured || !r.rule_text) {
  return [];   // one-off feedback, or learn errored — no notice
}
const txt = '📚 learned a possible rule from your edit:\n\n"' + r.rule_text + '"\n\n'
  + '(' + (r.scope || 'global') + ' rule · id ' + r.rule_id
  + ' · inactive until you approve)\n\n'
  + 'review all:  /rules\napprove this:  /approverule ' + r.rule_id;
return [{ json: { telegram_payload: { chat_id: adminChatId, text: txt } } }];

// FR-5 4.3b: format the bridge /rules response into a Telegram reply
const r = $input.item.json || {};
const adminChatId = $('Process Text Reply').item.json.admin_chat_id || 5532831477;
let txt;
if (r.ok && Array.isArray(r.pending)) {
  if (!r.pending.length) {
    txt = '📚 no behaviour rules pending review.';
  } else {
    txt = '📚 rules pending your approval (' + r.pending.length + '):\n\n'
      + r.pending.map(function (x) {
          return '• [' + x.id + '] (' + x.scope + ') ' + x.rule_text;
        }).join('\n\n')
      + '\n\napprove:  /approverule <id>\ndiscard:  /discardrule <id>';
  }
} else if (r.ok && r.action) {
  txt = r.action === 'activate'
    ? '✅ rule ' + r.rule_id + ' activated — it will now shape drafts.'
    : '🗑 rule ' + r.rule_id + ' discarded.';
} else {
  txt = '⚠️ rules service unavailable — try again shortly.'
    + (r.error ? '\n(' + r.error + ')' : '');
}
return [{ json: { telegram_payload: { chat_id: adminChatId, text: txt } } }];

// FR-4 4-B: confirm an autonomous-mode change to the operator
const r = $input.item.json || {};
const cmd = $('Process Text Reply').item.json;
const adminChatId = cmd.admin_chat_id || 5532831477;
let txt;
if (r.ok && cmd.mode_target === '__ALL__') {
  txt = '🛑 kill switch — every conversation is back to manual approval.';
} else if (r.ok && cmd.mode === 'autonomous') {
  txt = '🤖 autonomous mode ON for ' + (cmd.mode_target || 'this conversation')
    + '.\nclaude will draft and auto-send here — with the safety caps and a '
    + 'review window. reply /manual to a card from this customer to take it back.';
} else if (r.ok) {
  txt = '🙋 back to manual approval for '
    + (cmd.mode_target || 'this conversation') + '.';
} else {
  txt = '⚠️ could not change mode' + (r.error ? ': ' + r.error : '')
    + ' — try again.';
}
return [{ json: { telegram_payload: { chat_id: adminChatId, text: txt } } }];

