// FR-4 4-C: prep the autonomous-send branch for a freshly-posted draft
const sid = $('Save Telegram MsgID').item.json;
const draftId = sid.draft_id;
// Phase A (Redis-migration): use Queue & Format's in-execution draft.
let d = null;
try { d = ($('Queue & Format').item.json || {}).draft || null; } catch (e) { d = null; }
if (!d) return [];   // Phase C: Redis-only (staticData fallback removed)
const delay = 60 + Math.floor(Math.random() * 241);   // 60-300s, human-like
const mins = Math.max(1, Math.round(delay / 60));
const preview = (Array.isArray(d.messages) && d.messages.length > 1)
  ? d.messages.map((m, i) => (i + 1) + '. ' + m).join('\n')
  : (d.draft_text || '');
const lines = [
  '🤖 AUTO — auto-sends in ~' + mins + ' min unless you act',
  '(reply /manual here to stop · or ✏️ Edit · ❌ Skip)', '',
  '📩 ' + (d.customer_name || d.customer_phone), '',
  'they said: "' + (d.customer_message || '') + '"', '',
  '---', '💬 will send:', preview];
if (d && d.should_send_file && d.file_key) {
    (lines || []).push('📎 Suggested file: ' + d.file_key);
  }
  const reply_markup = { inline_keyboard: [
  [{ text: '✅ Send now', callback_data: 'send:' + draftId },
   { text: '✏️ Edit', callback_data: 'edit:' + draftId }],
  [{ text: '🔁 Regen', callback_data: 'regen:' + draftId },
   { text: '❌ Skip', callback_data: 'skip:' + draftId }],
  [{ text: '💳 Send Link', callback_data: 'paylink:' + draftId }],
      ...((d && d.should_send_file && d.file_key) ? [[{ text: '📎 Send File ('+(d.file_key)+')', callback_data: 'file:' + draftId }]] : [])
]  };
return [{ json: {
  draft_id: draftId,
  customer_id: d.customer_phone || '',
  customer_phone: d.customer_phone || '',
  telegram_message_id: sid.telegram_message_id || d.telegram_message_id,
      draft_text: d.draft_text || '',
      customer_name: d.customer_name || '',
  auto_delay_s: delay,
  auto_card_text: lines.join('\n'),
  auto_reply_markup: reply_markup
} }];

// FR-4 4-C: continue only if the bridge says this conversation is autonomous
const r = $input.item.json || {};
if ((r.mode || '') !== 'autonomous') return [];   // manual conversation — stop
return [{ json: r }];

// BUG-1 fix: decide via the Redis autosend state (Get Autosend), NOT n8n
// staticData — staticData is clobbered by concurrent executions across the
// Auto Wait countdown. armed === true => the operator did not intervene.
const r = $('Get Autosend').item.json || {};
if (r.armed !== true || !r.data) return [];
const d = r.data;
return [{ json: {
  draft_id: d.draft_id,
  customer_id: d.customer_phone || '',
  customer_phone: d.customer_phone || '',
  telegram_message_id: d.telegram_message_id,
  customer_name: d.customer_name || '',
  draft_text: d.draft_text || ''
} }];

// FR-4 4-C: send only if the caps cleared (bridge /autosend-check commit:true)
const r = $input.item.json || {};
if (r.auto_send !== true) return [];   // caps blocked / checkpoint — leave for operator
return [{ json: r }];

// FR-4 4-C: pass the auto-sent draft's identifiers to Edit Auto-Sent Card.
// The old staticData write of d.status='sent' was
// unreliable (concurrent-execution snapshot race) and had no readers, so
// it is gone — along with the unused d.auto_sent / d.messages_sent_count.
const dec = $('Auto Decide').item.json;
return [{ json: {
  draft_id: dec.draft_id,
  customer_phone: dec.customer_phone,
  customer_name: dec.customer_name,
  telegram_message_id: dec.telegram_message_id,
  draft_text: dec.draft_text
} }];

// FR-4 #3: alert Zayn when the autonomous-send branch fails at Auto Gate.
// Wired from Auto Gate's error output (onError: continueErrorOutput).
const it = $input.item || {};
const j = it.json || {};
const err = it.error || j.error || {};
let msg;
try {
  msg = err.message || err.description
    || (typeof err === 'string' ? err : '') || JSON.stringify(err);
} catch (e) { msg = 'unrecognised error'; }
let customer = '';
try {
  const u = $('Auto Prep').item.json || {};
  customer = u.customer_id || u.customer_phone || '';
} catch (e) {}
if (!customer) customer = j.customer_id || j.customer_phone || 'unknown';
const text = [
  '\uD83D\uDD34 AUTONOMOUS-SEND FAILURE',
  '',
  'node:     Auto Gate',
  'customer: ' + customer,
  'error:    ' + String(msg || 'unknown').slice(0, 400),
  'time:     ' + new Date().toISOString(),
  '',
  '\u26A0\uFE0F the autonomous gate check failed — the draft is still in your approval queue with its buttons; handle it normally.',
].join('\n');
return { json: { chat_id: 5532831477, alert_text: text } };

