// Read customer_id + draft_id from the unified paylink context.
// Phase C (Redis-migration): status persisted to Redis by 'Mark Link
// Sent Redis'; staticData write removed.
let cid = '';
let draftId = '';
try {
  const u = $('Unify Paylink Context').item.json;
  cid = u.customer_id || '';
  draftId = u.draft_id || '';
} catch (e) {}
return { json: { ok: true, draft_id: draftId, customer_id: cid,
  draft: { is_payment: true, customer_phone: cid } } };

// One node merges the two paylink paths (button click vs operator
// text reply) into a single $json shape so downstream nodes don't
// need cross-execution lookups like `$('Prep Paylink').item ? ...`.
// In n8n, accessing .item on a node that didn't run in this branch
// THROWS 'Node X hasn't been executed' — kills the chain at body
// evaluation, so the WAHA send never fires and the customer never
// receives the link.
//
// $json on THIS node = the Nomod call response (link_url, link_id,
// amount, ok). Then try each upstream context source; whichever
// actually ran provides the rest.
const nomod = $input.item.json || {};
let ctx = null;
try { ctx = $('Prep Paylink').item.json; } catch (e) { ctx = null; }
if (!ctx) {
  try { ctx = $('Build Paylink From Reply').item.json; } catch (e) { ctx = null; }
}
ctx = ctx || {};
// Pull the operator-facing draft text from staticData so we can
// merge it WITH the payment link in the customer message (was:
// payment link sent alone, without the LLM draft context).
// Also pull the customer_name for operator card display.
let draftText = '';
let custName = '';
// Phase C (Redis-migration): pull draft text + customer name from the
// Redis draft (bridge get) instead of staticData.
try {
  const _http = this.helpers.httpRequest.bind(this.helpers);
  const r = await _http({ method: 'POST',
    url: 'http://172.18.0.1:8788/queue',
    headers: { 'Content-Type': 'application/json',
      'X-Bridge-Token': $env.BRIDGE_TOKEN || '' },
    body: { action: 'get', draft_id: ctx.draft_id }, json: true, timeout: 8000 });
  if (r && r.found && r.draft) {
    draftText = r.draft.draft_text || '';
    custName = r.draft.customer_name || '';
  }
} catch (e) {}
return { json: {
  ok: nomod.ok === true,
  link_url: nomod.link_url || '',
  link_id: nomod.link_id || '',
  amount: nomod.amount || ctx.amount || 0,
  error: nomod.error || '',
  draft_id: ctx.draft_id || '',
  customer_id: ctx.customer_id || '',
  customer_name: ctx.customer_name || '',
  payment_summary: ctx.payment_summary || '',
  chat_id: ctx.chat_id || 5532831477,
  message_id: ctx.message_id || null,
  admin_chat_id: ctx.admin_chat_id || 5532831477,
  draft_text: draftText,
  customer_name: custName
} };

// Read the active draft from Parse Callback's enriched payload to
// pull customer_id, file_key, and a caption. Phase C (Redis-
// migration): the Redis draft (Parse Callback) is the sole source;
// /assist file-send creates a Redis-only draft, so this is correct.
const cb = $('Parse Callback').item.json || {};
const draftId = cb.draft_id;
const d = cb.draft || {};
const customerId = cb.customer_id || d.customer_phone;
const fileKey = d.file_key || cb.file_key || '';
const fileDesc = d.file_description || '';
const firstMsg = (d.messages && d.messages[0]) || d.draft_text || '';
const caption = (fileDesc && fileDesc.length > 5 ? fileDesc : '')
  || firstMsg || '';
return [{ json: {
  customer_id: customerId,
  draft_id: draftId,
  file_key: fileKey,
  caption: (caption || '').slice(0, 800),
  admin_chat_id: cb.admin_chat_id,
  reply_to_message_id: cb.message_id,
} }];

